CREATE MULTISET VOLATILE TABLE DQ_TEST_OUT_AGG AS (
SELECT CAST('OVERALL' AS VARCHAR(8)) AS PERIOD_LEVEL,CAST('ALL' AS VARCHAR(10)) AS PERIOD_VALUE,MAX(C.OVERALL_TOTAL_N) AS TOTAL_N,SUM(C.ACTUAL_TOTAL) AS ACTUAL_TOTAL,CAST(NULL AS DATE) AS POU_DT,MAX(C.ON1) AS N1,MAX(C.OL1) AS L1,MAX(C.OU1) AS U1,SUM(C.ACTUAL1) AS ACTUAL1,SUM(C.OO1) AS O1 FROM DQ_TEST_OUT_CHUNKS C
UNION ALL SELECT CAST('YEARLY' AS VARCHAR(8)) AS PERIOD_LEVEL,CAST(C.CHUNK_YEAR AS VARCHAR(10)) AS PERIOD_VALUE,MAX(C.YEARLY_TOTAL_N) AS TOTAL_N,SUM(C.ACTUAL_TOTAL) AS ACTUAL_TOTAL,MAX(C.POU_DT) AS POU_DT,MAX(C.YN1) AS N1,MAX(C.YL1) AS L1,MAX(C.YU1) AS U1,SUM(C.ACTUAL1) AS ACTUAL1,SUM(C.YO1) AS O1 FROM DQ_TEST_OUT_CHUNKS C WHERE C.CHUNK_VALUE<>'ALL' GROUP BY C.CHUNK_YEAR
UNION ALL SELECT CAST('MONTHLY' AS VARCHAR(8)) AS PERIOD_LEVEL,CAST(C.CHUNK_VALUE AS VARCHAR(10)) AS PERIOD_VALUE,MAX(C.MONTHLY_TOTAL_N) AS TOTAL_N,SUM(C.ACTUAL_TOTAL) AS ACTUAL_TOTAL,MAX(C.POU_DT) AS POU_DT,MAX(C.MN1) AS N1,MAX(C.ML1) AS L1,MAX(C.MU1) AS U1,SUM(C.ACTUAL1) AS ACTUAL1,SUM(C.MO1) AS O1 FROM DQ_TEST_OUT_CHUNKS C WHERE C.CHUNK_VALUE<>'ALL' GROUP BY C.CHUNK_VALUE
) WITH DATA PRIMARY INDEX (PERIOD_LEVEL,PERIOD_VALUE) ON COMMIT PRESERVE ROWS;

SELECT COUNT(*) AS PERIOD_ROWS,
       COUNT(DISTINCT PERIOD_LEVEL || ':' || PERIOD_VALUE) AS UNIQUE_PERIOD_KEYS,
       SUM(CASE
         WHEN PERIOD_LEVEL='OVERALL' AND PERIOD_VALUE='ALL' AND TOTAL_N=50 AND N1=50 AND O1=10 THEN 0
         WHEN PERIOD_LEVEL='YEARLY' AND PERIOD_VALUE='2005' AND TOTAL_N=20 AND N1=20 AND O1=2 THEN 0
         WHEN PERIOD_LEVEL='YEARLY' AND PERIOD_VALUE IN ('2006','2026','UNKNOWN') AND TOTAL_N=10 AND N1=10 AND O1=1 THEN 0
         WHEN PERIOD_LEVEL='MONTHLY' AND PERIOD_VALUE IN ('2005-01','2005-02','2006-01','2026-03','UNKNOWN') AND TOTAL_N=10 AND N1=10 AND O1=1 THEN 0
         ELSE 1 END) AS BAD_ROWS
FROM DQ_TEST_OUT_AGG;

SELECT PERIOD_LEVEL,PERIOD_VALUE,TOTAL_N,ACTUAL_TOTAL,N1,ACTUAL1,O1
FROM DQ_TEST_OUT_AGG ORDER BY PERIOD_LEVEL,PERIOD_VALUE;

DROP TABLE DQ_TEST_OUT_AGG;
DROP TABLE DQ_TEST_OUT_CHUNKS;
